let tl = gsap.timeline({});


var initMode = null;

let addTime = 250;

let st1, st2, st3;
let tl1 = gsap.timeline({});
let tl2 = gsap.timeline({});
let tl3 = gsap.timeline({});

let s3Width, b1Width, b2Width, b3Width, b4Width;
let animationSectionHeight, siteMainHeight;


let urlParams = new URLSearchParams(window.location.search);
let yValue = urlParams.get('y');

let animationSection = $('.animation__section')
function initAnimation(){
	if (window.innerWidth > 992 && animationSection.length > 0 ){
        if (initMode != 'desk'){
            siteMainHeight = $('.site-main').innerHeight();
            animationSectionHeight =  $('.animation__section').innerHeight();
            col2Height =  $('.js-animation__col--2').innerHeight();
            col3Height =  $('.js-animation__col--3').innerHeight();
            window.scrollTo({
                    top: 0,
                    behavior: "instant"
            });
            initMode = 'desk';
            reInit();
            initScrollAnimationDesktop();
        } else {
            reInit();
            siteMainHeight = $('.site-main').innerHeight();
            animationSectionHeight =  $('.animation__section').innerHeight();
            col2Height =  $('.js-animation__col--2').innerHeight();
            col3Height =  $('.js-animation__col--3').innerHeight();

            initScrollAnimationDesktop();
        }


	} else {
	    if (initMode == 'desk'){
            reInit();
        }
    }
}

initAnimation();
// checkYearValue();

var dwidth = $(window).width();
$(window).on('resize',function (){
	var wwidth = $(window).width();
	if(dwidth!==wwidth){
		initAnimation();
	}
});

function reInit(){
	if (typeof st1 !== "undefined") st1.kill();
	if (typeof st2 !== "undefined") st2.kill();
	if (typeof st3 !== "undefined") st3.kill();
	tl.clear();
	tl1.clear();
	tl2.clear();
	tl3.clear();
	gsap.set(
	    ".js-animation__col--2, .animation__bg.animation__bg__1, .js-animation__col--3",
        {clearProps:"all"}
    );
}

function initScrollAnimationDesktop(){

	tl1.fromTo(".js-animation__col--2", {
		y: "0%"
	}, {
		y: -1 * (col2Height - animationSectionHeight),
		// y: "-60%",
		duration: 0.2,
		ease: "none",
		onStart: function () {
			// $('.side-bar').removeClass('active');
			$('.side-bar').addClass('active', "blue");
			$('.side-bar__item--start').addClass('active');
		},
		// onReverseComplete: function () {
		// 	$('.side-bar').removeClass('active');
		// 	// $('.side-bar').addClass('active');
		// 	$('.side-bar__item--start').addClass('active');
		// }
	}, "0");
	tl1.fromTo(".animation__bg.animation__bg__1", {
		y: "0%"
	}, {
		y: -1* (col3Height - animationSectionHeight),
		// y: "-100%",
		duration: 0.1,
		ease: "none",

	}, "<");
	tl1.fromTo(".js-animation__col--3", {
		y: "23%"
	}, {
		y: -1 * (col3Height - animationSectionHeight),
		// y: "-70%",
		duration: 0.2,
		ease: "none",

	}, "<");


	ScrollTrigger.clearScrollMemory('manual') ;

	st1 = ScrollTrigger.create({
			// trigger: ".site-main",
			trigger: ".animation__section",
			pin: true,
			start: "top top",
			end: () =>   "+="+addTime+"%",
			scrub: 0, //2.5
			animation: tl1,
	});
}

$(document).on('click','.side-bar__list a[href^="#"]',function (){
	let href = $(this).attr('href');
	let target = $(href);

	let headerHeight = $('.section__header').innerHeight();

	if (target.length > 0 && target.parents('.pin-spacer').length > 0){
		event.preventDefault();
		let targetTop = target[0].offsetTop + target.parents('.pin-spacer')[0].offsetTop - headerHeight;
		if (href === '#main2'){
			let targetTop2 = $(window).innerHeight()*0.9 + target.parents('.pin-spacer')[0].offsetTop - headerHeight;
			if (targetTop2 < targetTop){
				targetTop = targetTop2;
			}
		}
		gsap.to(window, {
			scrollTo: { y: targetTop, autoKill: false },
			duration: 0,
		});
	} else if (target.length > 0) {
		event.preventDefault();
		let targetTop = target[0].offsetTop - headerHeight;
		$('html, body').animate({
			scrollTop: targetTop
		}, 0);
	}
});

